.candidato_lista_con_imagen {
  display: grid;
  grid-template-areas: "nombreLista nombreLista" "foto lista" "candidato candidato" "orden orden";
  grid-template-rows: 1fr minmax(40%, 2fr) 1fr;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  justify-items: center;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-nombre_lista {
  grid-area: nombreLista;
  text-align: center;
  font-size: 1.66rem;
  font-weight: bold;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-foto_candidato {
  grid-area: foto;
  width: 100%;
  height: 100%;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-foto_candidato img {
  object-fit: contain;
  width: 100%;
  max-height: 100%;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-lista {
  grid-area: lista;
  /*Agranda tamano del numero de lista*/
  font-size: 3.33rem;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-lista .numero-lista {
  font-size: 1em;
  text-align: center;
  font-weight: bold;
  text-transform: uppercase;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-lista .palabra-lista {
  font-size: 0.5em;
  text-align: center;
  font-weight: bold;
  text-transform: uppercase;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-lista .nombre-corto-lista {
  font-size: 0.5em;
  text-align: center;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-candidato_principal {
  grid-area: candidato;
  font-size: 1.66rem;
  text-align: center;
}
.candidato_lista_con_imagen .candidato_lista_con_imagen-candidato_principal_orden {
  grid-area: orden;
  font-size: 1.66rem;
  text-align: center;
  font-weight: bold;
}
